SELECT REGEXP_REPLACE(MobilePhoneModel, '^([^-]+)-(.+)$','\1' ) AS m, COUNT(DISTINCT UserID) AS u FROM hits WHERE MobilePhoneModel <> '' GROUP BY m ORDER BY u DESC;
SELECT REGEXP_REPLACE(Referer, '^https?://(?:www\.)?([^/]+)/.*$', '\1') AS k, AVG(STRLEN(Referer)) AS l, COUNT(*) AS c, MIN(Referer) FROM hits WHERE Referer <> '' GROUP BY k HAVING COUNT(*) > 100000 ORDER BY l DESC LIMIT 25;
SELECT REGEXP_REPLACE(OriginalURL, '^https?://(?:www\.)?([^/]+)/[^m]+m[^/]+/.*$', '\1') AS k, AVG(STRLEN(OriginalURL)) AS l, COUNT(*) AS c, MIN(OriginalURL) FROM hits WHERE OriginalURL <> '' GROUP BY k HAVING COUNT(*) > 100000 ORDER BY l DESC LIMIT 25;
SELECT REGEXP_REPLACE(OriginalURL, '^https?://(?:www\.)?([^/]+)/([^/]+)/([^/]+)/([^/]+)/([^/]+)/.*$', '\1') AS k, AVG(STRLEN(OriginalURL)) AS l, COUNT(*) AS c, MIN(OriginalURL) FROM hits WHERE OriginalURL <> '' GROUP BY k HAVING COUNT(*) > 100000 ORDER BY l DESC LIMIT 25;
SELECT REGEXP_REPLACE(OriginalURL, '^https?://(?:www\.)?([^/]+)/.*$', '\1') AS k, AVG(STRLEN(OriginalURL)) AS l, COUNT(*) AS c, MIN(OriginalURL) FROM hits WHERE OriginalURL <> '' GROUP BY k HAVING COUNT(*) > 200000 ORDER BY l DESC LIMIT 25;
SELECT REGEXP_REPLACE(OriginalURL, '^(http://[^/]+)/.*$', '\1') AS k, AVG(STRLEN(OriginalURL)) AS l, COUNT(*) AS c, MIN(OriginalURL) FROM hits WHERE OriginalURL <> '' GROUP BY k HAVING COUNT(*) > 200000 ORDER BY l DESC LIMIT 25;
SELECT REGEXP_REPLACE(OriginalURL, '^([^/]+//[^/]+)/.*$', '\1') AS k, AVG(STRLEN(OriginalURL)) AS l, COUNT(*) AS c, MIN(OriginalURL) FROM hits WHERE OriginalURL <> '' GROUP BY k HAVING COUNT(*) > 200000 ORDER BY l DESC LIMIT 25;